import assert from "node:assert/strict";
import test from "node:test";
import { Element, dom, flush } from "./playground-dom-fixture.mjs";
const initial = dom();
globalThis.HTMLElement = Element;
globalThis.document = initial.document;
const { PlaygroundPlaybackControls } = await import("./playground-playback-controls.js");
function fixture() {
  const { document, preview } = dom();
  globalThis.document = document;
  const calls = [];
  const player = {};
  for (const name of ["pause", "resume", "seek", "restartPlayback"]) {
    player[name] = async (time = 0) => { calls.push(name); return { time, playing: false }; };
  }
  const errors = [];
  const controls = new PlaygroundPlaybackControls(player, preview, { durationSeconds: 2, onError: (error) => errors.push(error) });
  return { controls, player, preview, calls, errors, range: preview.querySelector(".playback-scrubber"), output: preview.querySelector(".playback-time") };
}

test("source-owned progress moves despite busy/paused flags, without permitting playback commands", async () => {
  const f = fixture();
  f.controls.setControllable(false);
  f.controls.setBusy(true);
  f.controls.observe({ time: 0.4, playing: false, durationSeconds: 2 });
  assert.equal(f.range.value, "0.4");
  assert.equal(f.output.value, "0.40 s · live");
  f.controls.observe({ time: 2.5, playing: true, durationSeconds: 4 });
  assert.equal(f.range.value, "2.5"); assert.equal(f.range.max, "4");
  assert.equal(f.range.disabled, true);
  for (const selector of [".playback-toggle", ".playback-restart", ".playback-scrubber"]) {
    f.preview.querySelector(selector).dispatchEvent(new Event(selector.includes("scrubber") ? "input" : "click"));
  }
  await flush(); assert.deepEqual(f.calls, []);
});

test("completed replay observes exact time and playing state without an interpolated UI clock", () => {
  const f = fixture();
  f.controls.observe({ time: 1.2, playing: true });
  assert.equal(f.range.value, "1.2");
  f.controls.observe({ time: 2, playing: false });
  assert.equal(f.output.value, "2.00 / 2.00 s");
  assert.equal(f.preview.querySelector(".playback-toggle").textContent, "Play");
});

test("polling cannot override an in-flight user's seek", async () => {
  const f = fixture(); let resolve;
  f.player.seek = () => new Promise((done) => { resolve = done; });
  f.range.value = "1.5"; f.range.dispatchEvent(new Event("input"));
  f.controls.observe({ time: 0.2, playing: true });
  assert.equal(f.range.value, "1.5");
  resolve({ time: 1.5, playing: false }); await flush();
  assert.equal(f.output.value, "1.50 / 2.00 s");
});

test("retired command completion cannot mutate a replacement's controls or error status", async () => {
  const f = fixture(); let reject;
  f.player.pause = () => new Promise((_, fail) => { reject = fail; });
  f.preview.querySelector(".playback-toggle").dispatchEvent(new Event("click"));
  f.controls.destroy();
  const replacement = new PlaygroundPlaybackControls(f.player, f.preview, { durationSeconds: 3 });
  replacement.sync({ time: 0.75, playing: false });
  reject(new Error("old worker terminated")); await flush();
  assert.equal(replacement.element.dataset.playing, "false");
  assert.equal(replacement.element.dataset.busy, "false");
  assert.equal(f.preview.querySelector(".playback-scrubber").value, "0.75");
  assert.deepEqual(f.errors, []);
});

// Source replacement is a host lifecycle operation, not an animation scheduler.
// Stop on the first edit; debounce only the next full-source Run. Each delayed
// request checks both edit freshness and selection identity after cancellation.
export function createSourceRestart({
  stop,
  run,
  currentSelection,
  onError,
  delayMs = 500,
  setTimer = setTimeout,
  clearTimer = clearTimeout,
}) {
  let version = 0;
  let timer = null;
  let stopping = null;
  let disposed = false;
  let explicitStart = null;
  let reportedVersion = -1;

  function cancel() {
    version += 1;
    if (timer !== null) clearTimer(timer);
    timer = null;
  }

  function stopCurrent() {
    if (stopping !== null) return stopping;
    // Calling stop synchronously invalidates the current run before an older
    // authoring/reconciliation/metrics promise can commit another result.
    let task;
    try { task = Promise.resolve(stop()); }
    catch (error) { task = Promise.reject(error); }
    stopping = task;
    void task.then(
      () => { if (stopping === task) stopping = null; },
      () => { if (stopping === task) stopping = null; },
    );
    return task;
  }

  function report(error, requestVersion) {
    if (disposed || version !== requestVersion || reportedVersion === requestVersion) return;
    reportedVersion = requestVersion;
    onError(error);
  }

  async function start(requestVersion, selection, retirement, onStarted = () => {}) {
    try {
      await retirement;
      if (disposed || version !== requestVersion || currentSelection() !== selection) return;
      onStarted();
      return await run();
    } catch (error) {
      report(error, requestVersion);
    }
  }

  function edited({ composing = false } = {}) {
    if (disposed) return;
    cancel();
    const requestVersion = version;
    const selection = currentSelection();
    const retirement = stopCurrent();
    // Attach a rejection handler immediately, even while the user is composing.
    void retirement.catch((error) => {
      report(error, requestVersion);
    });
    if (composing) return;
    timer = setTimer(() => {
      timer = null;
      void start(requestVersion, selection, retirement);
    }, delayMs);
  }

  function runNow() {
    if (disposed) return Promise.resolve();
    if (explicitStart?.version === version) return explicitStart.promise;
    cancel();
    const gate = { version, promise: null };
    const release = () => { if (explicitStart === gate) explicitStart = null; };
    gate.promise = start(version, currentSelection(), stopping, release).finally(release);
    explicitStart = gate;
    return gate.promise;
  }

  function dispose() {
    disposed = true;
    cancel();
  }

  return Object.freeze({ edited, runNow, cancel, dispose });
}

import assert from "node:assert/strict";
import test from "node:test";
import { createSourceRestart } from "./playground-source-restart.js";

const deferred = () => { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; };
const flush = async () => { for (let i = 0; i < 12; i += 1) await Promise.resolve(); };
function harness() {
  let selection = "one";
  let source = "initial";
  const timers = new Map();
  const stops = [];
  const runs = [];
  const errors = [];
  let timerId = 0;
  const controller = createSourceRestart({
    stop() { const gate = deferred(); stops.push(gate); return gate.promise; },
    run() { const gate = deferred(); runs.push({ source, selection, gate }); return gate.promise; },
    currentSelection: () => selection,
    onError: (error) => errors.push(error),
    setTimer(callback) { const id = ++timerId; timers.set(id, callback); return id; },
    clearTimer(id) { timers.delete(id); },
  });
  return {
    controller, stops, runs, errors,
    edit(text, options) { source = text; controller.edited(options); },
    select(id) { selection = id; },
    tick() { const callbacks = [...timers.values()]; timers.clear(); for (const callback of callbacks) callback(); },
    get timers() { return timers.size; },
  };
}

test("editing stops synchronously; a typing burst submits only the latest source after retirement", async () => {
  const h = harness();
  h.edit("first");
  assert.equal(h.stops.length, 1);
  assert.equal(h.runs.length, 0);
  h.edit("second");
  h.edit("latest");
  assert.equal(h.stops.length, 1);
  assert.equal(h.timers, 1);
  h.tick(); await flush();
  assert.equal(h.runs.length, 0, "replacement must await old context retirement");
  h.stops[0].resolve(); await flush();
  assert.deepEqual(h.runs.map((run) => run.source), ["latest"]);
  h.runs[0].gate.resolve(); await flush();
  h.tick(); await flush();
  assert.equal(h.runs.length, 1);
});

test("an edit during cancellation cannot start at an older debounce deadline", async () => {
  const h = harness();
  h.edit("first"); h.tick();
  h.edit("latest");
  h.stops[0].resolve(); await flush();
  assert.equal(h.runs.length, 0);
  h.tick(); await flush();
  assert.equal(h.runs[0].source, "latest");
  h.runs[0].gate.resolve();
});

test("editing an active replacement stops it without waiting for the whole animation", async () => {
  const h = harness();
  h.edit("first"); h.stops[0].resolve(); h.tick(); await flush();
  h.edit("second");
  assert.equal(h.stops.length, 2);
  h.stops[1].resolve(); h.tick(); await flush();
  assert.deepEqual(h.runs.map((run) => run.source), ["first", "second"]);
  h.runs[0].gate.resolve(); h.runs[1].gate.resolve();
});

test("Run now flushes pending edits without a duplicate delayed Run", async () => {
  const h = harness();
  h.edit("draft");
  const explicit = h.controller.runNow();
  assert.equal(h.timers, 0);
  h.stops[0].resolve(); await flush();
  assert.equal(h.runs[0].source, "draft");
  h.tick(); await flush(); assert.equal(h.runs.length, 1);
  h.runs[0].gate.resolve("done");
  assert.equal(await explicit, "done");
});

test("IME composition stops the old preview but submits only committed text", async () => {
  const h = harness();
  h.edit("partial", { composing: true });
  assert.equal(h.stops.length, 1); assert.equal(h.timers, 0);
  h.tick(); h.stops[0].resolve(); await flush();
  assert.equal(h.runs.length, 0);
  h.edit("committed"); h.stops[1].resolve(); h.tick(); await flush();
  assert.equal(h.runs[0].source, "committed");
  h.runs[0].gate.resolve();
});

test("a selection change or disposal retires pending source submissions", async () => {
  for (const action of ["select", "dispose"]) {
    const h = harness();
    h.edit("draft"); h.tick();
    if (action === "select") h.select("two"); else h.controller.dispose();
    h.stops[0].resolve(); await flush();
    assert.equal(h.runs.length, 0);
  }
});

test("stale run failures do not overwrite newer edit status, and a later run recovers", async () => {
  const h = harness();
  h.edit("first"); h.stops[0].resolve(); h.tick(); await flush();
  h.edit("second"); h.stops[1].resolve(); h.tick(); await flush();
  h.runs[0].gate.reject(new Error("stale failure"));
  h.runs[1].gate.resolve(); await flush();
  assert.deepEqual(h.errors, []);
  h.edit("bad syntax"); h.stops[2].resolve(); h.tick(); await flush();
  h.runs[2].gate.reject(new Error("SyntaxError")); await flush();
  assert.equal(h.errors.length, 1);
  h.edit("repaired"); h.stops[3].resolve(); h.tick(); await flush();
  assert.equal(h.runs[3].source, "repaired");
  h.runs[3].gate.resolve();
});

test("duplicate Run callers both await the same replacement result", async () => {
  const h = harness();
  h.edit("draft");
  const first = h.controller.runNow();
  const second = h.controller.runNow();
  h.stops[0].resolve(); await flush();
  assert.equal(h.runs.length, 1);
  h.runs[0].gate.resolve("latest result");
  assert.deepEqual(await Promise.all([first, second]), ["latest result", "latest result"]);
});

test("retirement failure is reported once and never starts an overlapping run", async () => {
  const h = harness();
  h.edit("draft"); h.tick();
  h.stops[0].reject(new Error("retirement failed")); await flush();
  assert.equal(h.errors.length, 1);
  assert.equal(h.runs.length, 0);
});
